            return math.pi * radius ** 2
        elif self.shape_type == "rectangle":
            length = self.additional_attributes.get("length")
            width = self.additional_attributes.get("width")
            if length is None or width is None:
                raise ValueError("Length and width are required for rectangle shape")
            return length * width
        elif self.shape_type == "triangle":
            base = self.additional_attributes.get("base")
            height = self.additional_attributes.get("height")
            if base is None or height is None:
                raise ValueError("Base and height are required for triangle shape")
            return 0.5 * base * height
        else:
            raise ValueError(f"Unsupported shape type: {self.shape_type}")
